<script lang="ts">import{page}from"$app/state";import{goto}from"$app/navigation";import{movies}from"../../../../../shared/catalog";let dialog:HTMLDialogElement;let rating=$state<number|null>(null);let movie=$derived(movies.find(item=>item.id===page.params.id));</script>
<svelte:head><title>{movie?movie.title:"Película no encontrada"} · Prisma muestra</title></svelte:head>
<main class="app"><header class="top"><button class="btn" onclick={()=>goto("/")}>← Volver</button><span class="kicker">FICHA DE PRUEBA</span></header>{#if movie}<section class="hero" style:--n={movie.seed}><span class="kicker">{movie.genre.toUpperCase()} · {movie.runtime} MIN</span><h1>{movie.title}</h1><p>{movie.year} · {movie.status}</p></section><div class="actions"><button class="btn primary" onclick={()=>dialog.showModal()}>{rating===null?"Calificar":rating+"/10"}</button><button class="btn" onclick={()=>document.getElementById("viewings")?.scrollIntoView({behavior:"smooth"})}>Visionados</button></div><section class="section"><h3>Sinopsis</h3><p>Texto sintético idéntico para comparar ambos frameworks. No se consulta ningún catálogo externo.</p></section><section class="section" id="viewings"><h3>Visionados</h3><p>Dos registros ficticios independientes; no se guardan en almacenamiento.</p></section>{:else}<h1>Película no encontrada</h1>{/if}</main>
<dialog class="dialog" bind:this={dialog} aria-labelledby="rating-title"><h2 id="rating-title">Calificar esta película</h2><form onsubmit={e=>{e.preventDefault();const n=Number(new FormData(e.currentTarget as HTMLFormElement).get("rating"));if(n>=1&&n<=10)rating=n;dialog.close()}}><label>Nota<select name="rating" required><option value="">Selecciona</option>{#each Array.from({length:10},(_,i)=>i+1) as n}<option value={n}>{n}/10</option>{/each}</select></label><div class="row"><button class="btn" type="button" onclick={()=>dialog.close()}>Cancelar</button><button class="btn primary" type="submit">Guardar nota</button></div></form></dialog>